package com.velorise.emc;
import com.velorise.emc.common.DeepboundStorageProfile;import com.velorise.emc.common.WirelessCoreTier;import net.minecraft.core.NonNullList;import net.minecraft.nbt.CompoundTag;import net.minecraft.world.ContainerHelper;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;
/** Persistent per-player Deepbound Ender inventory. */
public final class PersonalDeepboundEnderStorage implements DeepboundStorageAccess{private static final String ROOT="VeloriseEMCDeepboundEnderStorage";private final Player player;private final WirelessCoreTier tier;private final int locked;private NonNullList<ItemStack> items=NonNullList.withSize(DeepboundStorageProfile.MAX_SLOTS,ItemStack.EMPTY);public PersonalDeepboundEnderStorage(Player p,WirelessCoreTier t,int l){player=p;tier=t==null?WirelessCoreTier.I:t;locked=l;ContainerHelper.loadAllItems(p.getPersistentData().getCompound(ROOT),items,p.registryAccess());}public static void copyPlayerData(Player from,Player to){if(from==null||to==null)return;CompoundTag source=from.getPersistentData().getCompound(ROOT);if(!source.isEmpty())to.getPersistentData().put(ROOT,source.copy());}private void save(){CompoundTag tag=new CompoundTag();ContainerHelper.saveAllItems(tag,items,player.registryAccess());player.getPersistentData().put(ROOT,tag);}@Override public WirelessCoreTier getCoreTier(){return tier;}@Override public int getAccessibleSlotCount(){return DeepboundStorageProfile.slotCount(tier);}@Override public int clampPage(int p){return DeepboundStorageProfile.clampPage(tier,p);}@Override public boolean stillValid(Player p){return p==player&&p.isAlive();}@Override public int lockedPlayerSlot(){return locked;}@Override public int getContainerSize(){return DeepboundStorageProfile.MAX_SLOTS;}@Override public boolean isEmpty(){return items.stream().allMatch(ItemStack::isEmpty);}@Override public ItemStack getItem(int i){return i>=0&&i<items.size()?items.get(i):ItemStack.EMPTY;}@Override public ItemStack removeItem(int i,int n){ItemStack o=ContainerHelper.removeItem(items,i,n);if(!o.isEmpty())save();return o;}@Override public ItemStack removeItemNoUpdate(int i){ItemStack o=ContainerHelper.takeItem(items,i);save();return o;}@Override public void setItem(int i,ItemStack s){if(i<0||i>=items.size())return;items.set(i,s);if(!s.isEmpty()&&s.getCount()>getMaxStackSize())s.setCount(getMaxStackSize());save();}@Override public boolean canPlaceItem(int i,ItemStack s){return DeepboundStorageProfile.isAccessibleSlot(tier,i)&&!s.is(VeloriseEMC.DEEPBOUND_ENDER_CHEST_ITEM.get());}@Override public void setChanged(){save();}@Override public void clearContent(){items.clear();save();}}
